export function LightboxGallery({
  caption = "{{caption}}",
  accent = "{{accent}}",
  radius = {{radius}},
  dimmed = {{dimmed}},
}) {
  return (
    <div style={{ maxWidth: 200, font: "13px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <a href="#lb-photo-react" aria-label={`Open enlarged image: ${caption}`}
        style={{ display: "block", overflow: "hidden", border: "1px solid #24143022", borderRadius: radius }}>
        <svg viewBox="0 0 120 90" width="100%" height="100%" role="img" aria-hidden="true"><rect width="120" height="90" fill="#BFD9F2" /><circle cx="60" cy="45" r="22" fill="#A8E6C1" /></svg>
      </a>
      <div id="lb-photo-react" role="dialog" aria-modal="true" aria-label={caption}
        style={{ position: "fixed", inset: 0, display: "none", alignItems: "center", justifyContent: "center",
          background: dimmed ? "#241430e6" : "#24143099", zIndex: 50 }}>
        <a href="#" aria-label="Close enlarged image"
          style={{ position: "absolute", top: 16, right: 16, width: 32, height: 32, borderRadius: "50%",
            display: "flex", alignItems: "center", justifyContent: "center", color: "#241430",
            textDecoration: "none", fontSize: 20, lineHeight: 1, background: accent }}>
          &times;
        </a>
        <figure style={{ margin: 0, maxWidth: 360, width: "90%" }}>
          <svg viewBox="0 0 400 260" width="100%" height="100%" role="img" aria-hidden="true" style={{ display: "block", borderRadius: 8 }}><rect width="400" height="260" fill="#241430" /><circle cx="200" cy="130" r="70" fill={accent} /></svg>
          <figcaption style={{ marginTop: 8, color: "#FAF7F2", textAlign: "center" }}>{caption}</figcaption>
        </figure>
      </div>
      {/* :target only works with static anchors; in React, drive the dialog's open state from props/state instead. */}
    </div>
  );
}
